def uri(p,mime):
 if mime=='image/png':
  buf=io.BytesIO();Image.open(p).convert('RGB').save(buf,format='JPEG',quality=94,optimize=True);data=buf.getvalue();mime='image/jpeg'
 else:data=p.read_bytes()
 return 'data:'+mime+';base64,'+base64.b64encode(data).decode()
