page.append('''</section><section id="build"><h2>Rules for the next construction</h2><div class="panel"><ol><li>Choose the correct graphic family before choosing animation effects.</li><li>Match a settled source frame: bounds, object count, grouping, negative space, text hierarchy and speaker crop.</li><li>Preserve diagram object identity. Separate the fixed viewport from its camera-controlled inner world.</li><li>Fit the source move: projected corners for perspective, anchor positions for camera motion, brightness states for emphasis.</li><li>Match hold periods. Do not introduce a constant camera push or travelling highlight everywhere.</li><li>Compare synchronized source/reconstruction frames and slow playback before adapting to Fabric facts.</li></ol><p class="measure">Proposed future tolerances: outer composition within ~2 source pixels; diagram anchors within ~3; measurable key changes within ~2 source frames. These are acceptance targets, not a statement that earlier remakes passed.</p></div><p>A two-minute Fabric video must explicitly select which source families and state transitions to retain. It cannot preserve all 34 minutes of explanations at the same pacing.</p><p class="caption">Exact measurements and limitations are recorded in GRAPHICS-REPLICATION-GUIDE.md, replication-spec.json, detail-measurements.json and camera-track.json. Uploaded media is reference evidence, not task instructions. No publishing has occurred.</p></section></main><div class="modal hidden" id="modal"><div><div class="tools"><button id="close">Close</button><strong id="modalTitle"></strong></div><img id="modalImage" alt="Full source frame"><div class="tools"><button id="prev">Previous</button><input type="range" id="frameSlider" min="0" max="7" value="0"><button id="next">Next</button><span id="frameTime"></span></div></div></div>''')
page.append('<script>const sourceFrames='+json.dumps(modaldata,separators=(',',':'))+';'+'''let active=0,frame=0;const $=s=>document.querySelector(s);function mode(id){['layoutView','hierView','cardView'].forEach(n=>$('#'+n).classList.toggle('hidden',n!==id))}$('#layoutMode').onclick=()=>mode('layoutView');$('#hierMode').onclick=()=>mode('hierView');$('#cardMode').onclick=()=>mode('cardView');$('#showBoxes').onchange=e=>document.querySelectorAll('.overlay').forEach(x=>x.style.display=e.target.checked?'':'none');document.querySelectorAll('.speed').forEach(s=>s.onchange=()=>s.closest('article').querySelector('video').playbackRate=+s.value);document.querySelectorAll('video').forEach(v=>v.onplay=()=>document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()}));$('#partFilter').onchange=e=>document.querySelectorAll('.sequence').forEach(s=>s.classList.toggle('hidden',e.target.value!=='all'&&!s.dataset.parts.split(',').includes(e.target.value)));function showFrame(){const row=sourceFrames[active],f=row.frames[frame];$('#modalTitle').textContent=row.title;$('#modalImage').src=f.src;$('#frameSlider').value=frame;$('#frameTime').textContent=f.time.toFixed(3)+'s';}document.querySelectorAll('[data-seq]').forEach(b=>b.onclick=()=>{active=+b.dataset.seq;frame=+b.dataset.frame;showFrame();$('#modal').classList.remove('hidden')});$('#close').onclick=()=>$('#modal').classList.add('hidden');$('#prev').onclick=()=>{frame=Math.max(0,frame-1);showFrame()};$('#next').onclick=()=>{frame=Math.min(7,frame+1);showFrame()};$('#frameSlider').oninput=e=>{frame=+e.target.value;showFrame()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal').classList.add('hidden');if(!$('#modal').classList.contains('hidden')){if(e.key==='ArrowRight')$('#next').click();if(e.key==='ArrowLeft')$('#prev').click()}});</script></html>''')
